/**
 * Tenant branding — a company's logo, name and accent colour on the pages its partners see (portal and link pages).
 *
 * A tenant gives a colour; the design system decides where it may go. The colour is never written into a component:
 * `brandingAttrs(branding)` returns, for the ROOT of a branded subtree, a `data-brand` attribute naming the roles the
 * colour passed (`primary-light accent-light accent-dark`) and a `style` of `--nds-brand-*` custom properties. The
 * stylesheet `styles/branding.css` (generated by `tools/generate-tokens-css.ts` from `brandBlocks`) maps them onto the
 * SAFE semantic tokens inside that subtree, per theme:
 *
 *   --nds-primary        the main action's fill and accent text       only when the colour passes the PRIMARY rule
 *   --nds-primary-hover  the same fill under the pointer               derived from it (darker in light, lighter in dark)
 *   --nds-brand-accent   decoration: a header rule, a current-tab bar  only when the colour passes the ACCENT rule;
 *                                                                      else the subtree's `--nds-primary`
 *
 * Nothing else changes: text, surfaces, borders, links (`--nds-text-link`), focus, status colours and the label on a
 * filled button (`--nds-text-inverse`) keep the design system's values, so every other contrast pair holds unchanged.
 * A role the colour failed is simply not named in `data-brand`, so no rule fires and the token keeps the value it
 * inherits — the design system's own, in that theme. No default is restated anywhere.
 *
 * ## The contrast rule, per theme
 *
 * PRIMARY — the same seven pairs, at the same 7:1, that `scripts/check-nds-contrast.mjs` holds `--nds-primary` to (R-49):
 * the colour as text on `--nds-bg`, `--nds-surface`, `--nds-surface-raised`, `--nds-surface-sunken` and
 * `--nds-surface-hover`; `--nds-text-inverse` on the colour; `--nds-text-inverse` on the derived hover fill.
 * ACCENT — 3:1 (WCAG 2.2 1.4.11, a graphical object) against the same five grounds.
 *
 * Light and dark are judged apart: a dark colour that passes on white fails on the dark canvas, so `accentDark` may give
 * a second colour for dark (absent: `accent` is tried there too). A colour that fails a rule in a theme is not used for
 * that role in that theme. Nothing is adjusted or "fixed up" — the tenant's colour is shown as given or not at all, and
 * `checkBranding` says which and why, so a settings screen can tell the person.
 *
 * ## Applying it
 *
 *   import '@nexus/ui/styles/branding.css'          // once, in the app that shows branded pages
 *   <div {...brandingAttrs(tenant.branding)}>…portal…</div>
 *
 * The stylesheet is the app's to load (as `patterns/shell/app-rail.css` is): the tokens CSS every page loads is not
 * touched, so an app without branded pages carries none of it. `brandingAttrs` is plain (no React), so a server layout
 * can call it. A Modal or Popover renders into `<body>`, outside the subtree: a screen that is all one brand puts the
 * attributes on `<body>`, as `densityAttrs` does. The theme is the `.dark` class the tokens CSS uses (on `<html>` or any
 * ancestor). The logo and the name come back from `checkBranding` (`logoUrl` is dropped unless it is https, a path on
 * this site or an inline image) for the page's header to draw.
 */
import type { CSSProperties } from 'react'
import { palette } from './colors'

export type BrandTheme = 'light' | 'dark'

export const BRAND_THEMES = ['light', 'dark'] as const satisfies readonly BrandTheme[]

/** What a tenant gives. */
export interface BrandingTokens {
  /** The company's display name: the logo's text alternative, and the words shown where there is no logo. */
  name: string
  /** The logo file: an https address, a path on this site (`/files/logo.png`) or an inline image (`data:image/…`). */
  logoUrl?: string | null
  /** A logo for the dark theme (a light version). Absent: `logoUrl` in both. */
  logoDarkUrl?: string | null
  /** The accent colour, `#rrggbb` or `#rgb`. */
  accent?: string | null
  /** The accent for the dark theme. Absent: `accent` is tried in dark too. */
  accentDark?: string | null
}

/** The bars a colour must clear. */
export const BRAND_CONTRAST = {
  /** `--nds-primary`'s bar in `check-nds-contrast.mjs` (body text, AAA, R-49). */
  primary: 7,
  /** A graphical object (WCAG 2.2 1.4.11). */
  accent: 3,
} as const

/** How far the hover fill moves from the colour: toward black in light, toward white in dark. */
export const BRAND_HOVER_MIX = 0.18

type Ground = '--nds-bg' | '--nds-surface' | '--nds-surface-raised' | '--nds-surface-sunken' | '--nds-surface-hover'

interface ThemeGrounds {
  grounds: Readonly<Record<Ground, string>>
  /** `--nds-text-inverse`: the label on a filled button. */
  inverse: string
}

/**
 * The colours the rule measures against, per theme. Light ones come from the palette; the dark ones are the literals of
 * `css-vars.ts`'s dark block (their only home), restated here because importing `css-vars.ts` would put the whole token
 * table in every bundle that reads this file. `branding.vitest.test.ts` resolves each name from `css-vars.ts` and fails
 * when one drifts.
 */
export const BRAND_GROUNDS: Readonly<Record<BrandTheme, ThemeGrounds>> = {
  light: {
    grounds: {
      '--nds-bg': palette.grey[50],
      '--nds-surface': palette.white,
      '--nds-surface-raised': palette.grey[25],
      '--nds-surface-sunken': palette.grey[100],
      '--nds-surface-hover': palette.grey[75],
    },
    inverse: palette.white,
  },
  dark: {
    grounds: {
      '--nds-bg': '#14223a',
      '--nds-surface': '#18263b',
      '--nds-surface-raised': '#1f2c3d',
      '--nds-surface-sunken': '#1a2330',
      '--nds-surface-hover': '#1f2c3d',
    },
    inverse: '#14223a',
  },
}

// ── colour maths (WCAG 2.2 relative luminance) ──────────────────────────────────────────────────────────────────────

type Rgb = readonly [number, number, number]

/** `#rrggbb` (lower case) for `#rgb` / `#rrggbb` in any case, with or without spaces around; null for anything else. */
export function normalizeHex(value: string | null | undefined): string | null {
  if (typeof value !== 'string') return null
  const v = value.trim().toLowerCase()
  if (/^#[0-9a-f]{6}$/.test(v)) return v
  if (/^#[0-9a-f]{3}$/.test(v)) return `#${v[1]}${v[1]}${v[2]}${v[2]}${v[3]}${v[3]}`
  return null
}

const rgbOf = (hex: string): Rgb => [1, 3, 5].map((i) => parseInt(hex.slice(i, i + 2), 16)) as unknown as Rgb
const hexOf = (rgb: Rgb): string => `#${rgb.map((c) => Math.round(c).toString(16).padStart(2, '0')).join('')}`
const channel = (c: number): number => {
  const s = c / 255
  return s <= 0.03928 ? s / 12.92 : ((s + 0.055) / 1.055) ** 2.4
}
const luminance = (hex: string): number => {
  const [r, g, b] = rgbOf(hex)
  return 0.2126 * channel(r) + 0.7152 * channel(g) + 0.0722 * channel(b)
}

/** The WCAG contrast ratio of two `#rrggbb` colours, 1–21. */
export function contrastRatio(a: string, b: string): number {
  const x = luminance(a)
  const y = luminance(b)
  return (Math.max(x, y) + 0.05) / (Math.min(x, y) + 0.05)
}

/** `amount` (0–1) of `toward` mixed into `hex`, in sRGB — what `color-mix(in srgb, …)` draws. */
export function mixHex(hex: string, toward: string, amount: number): string {
  const a = rgbOf(hex)
  const b = rgbOf(toward)
  return hexOf([0, 1, 2].map((i) => a[i] + (b[i] - a[i]) * amount) as unknown as Rgb)
}

/** The hover fill for a brand colour in a theme: darker in light, lighter in dark (the design system's own direction). */
export function brandHover(hex: string, theme: BrandTheme): string {
  return mixHex(hex, theme === 'light' ? '#000000' : '#ffffff', BRAND_HOVER_MIX)
}

// ── the check ───────────────────────────────────────────────────────────────────────────────────────────────────────

/** One measured pair: what it is, its ratio (2 decimals) and the bar it had to clear. */
export interface BrandPair {
  /** `"text on --nds-surface"`, `"--nds-text-inverse on fill"`, `"--nds-text-inverse on hover"`, `"accent on --nds-bg"`. */
  pair: string
  ratio: number
  min: number
}

/** What happens to the colour in one theme. */
export interface BrandThemeVerdict {
  theme: BrandTheme
  /** The colour tried here, normalised; null when none was given. */
  colour: string | null
  /** The tenant gave something that is not `#rgb` / `#rrggbb`. */
  invalid: boolean
  /** The colour is the main action's fill and accent text here. */
  primary: boolean
  /** The colour is the decorative accent here. */
  accent: boolean
  /** The derived hover fill (when `primary`). */
  hover: string | null
  /** Every pair measured, weakest first; empty when there was no colour to measure. */
  pairs: BrandPair[]
  /** The pairs below their bar, weakest first: why a role fell back to the design system's colour. */
  failures: BrandPair[]
}

export interface BrandingCheck {
  name: string
  /** The logo for light, when it is an address the page may load; undefined otherwise. */
  logoUrl?: string
  /** The logo for dark (falls back to `logoUrl`). */
  logoDarkUrl?: string
  light: BrandThemeVerdict
  dark: BrandThemeVerdict
}

const r2 = (x: number): number => Math.round(x * 100) / 100

function judge(raw: string | null | undefined, theme: BrandTheme): BrandThemeVerdict {
  const given = typeof raw === 'string' && raw.trim() !== ''
  const colour = normalizeHex(raw)
  const none: BrandThemeVerdict = { theme, colour, invalid: given && !colour, primary: false, accent: false, hover: null, pairs: [], failures: [] }
  if (!colour) return none
  const { grounds, inverse } = BRAND_GROUNDS[theme]
  const hover = brandHover(colour, theme)
  const primaryPairs: BrandPair[] = [
    ...Object.entries(grounds).map(([name, ground]) => ({ pair: `text on ${name}`, ratio: r2(contrastRatio(colour, ground)), min: BRAND_CONTRAST.primary })),
    { pair: '--nds-text-inverse on fill', ratio: r2(contrastRatio(inverse, colour)), min: BRAND_CONTRAST.primary },
    { pair: '--nds-text-inverse on hover', ratio: r2(contrastRatio(inverse, hover)), min: BRAND_CONTRAST.primary },
  ]
  const accentPairs: BrandPair[] = Object.entries(grounds).map(([name, ground]) => ({
    pair: `accent on ${name}`,
    ratio: r2(contrastRatio(colour, ground)),
    min: BRAND_CONTRAST.accent,
  }))
  const below = (p: BrandPair) => p.ratio < p.min
  const byRatio = (a: BrandPair, b: BrandPair) => a.ratio - b.ratio
  const primary = !primaryPairs.some(below)
  const accent = !accentPairs.some(below)
  const pairs = [...primaryPairs, ...accentPairs].sort(byRatio)
  return { ...none, primary, accent, hover: primary ? hover : null, pairs, failures: pairs.filter(below) }
}

/** A logo address the page may load: https, a path on this site, or an inline raster/SVG image. Anything else: undefined. */
export function safeLogoUrl(value: string | null | undefined): string | undefined {
  if (typeof value !== 'string') return undefined
  const v = value.trim()
  if (/^https:\/\/[^\s]+$/i.test(v)) return v
  if (/^\/(?!\/)[^\s]*$/.test(v)) return v
  if (/^data:image\/(png|jpeg|gif|webp|avif|svg\+xml);base64,[a-z0-9+/=]+$/i.test(v)) return v
  return undefined
}

/** What the design system will do with a tenant's branding, per theme, and why. */
export function checkBranding(branding: BrandingTokens): BrandingCheck {
  const logoUrl = safeLogoUrl(branding.logoUrl)
  const logoDarkUrl = safeLogoUrl(branding.logoDarkUrl) ?? logoUrl
  const darkRaw = typeof branding.accentDark === 'string' && branding.accentDark.trim() !== '' ? branding.accentDark : branding.accent
  return {
    name: branding.name.trim(),
    ...(logoUrl ? { logoUrl } : {}),
    ...(logoDarkUrl ? { logoDarkUrl } : {}),
    light: judge(branding.accent, 'light'),
    dark: judge(darkRaw, 'dark'),
  }
}

/** The custom-property names `brandingStyle` may set — one set per theme. */
export const BRAND_VARS = {
  light: { primary: '--nds-brand-primary-light', hover: '--nds-brand-primary-hover-light', accent: '--nds-brand-accent-light' },
  dark: { primary: '--nds-brand-primary-dark', hover: '--nds-brand-primary-hover-dark', accent: '--nds-brand-accent-dark' },
} as const

export type BrandStyle = Partial<Record<(typeof BRAND_VARS)[BrandTheme][keyof (typeof BRAND_VARS)['light']], string>>

/** A role in a theme, as `data-brand` names it. */
export type BrandRole = 'primary-light' | 'accent-light' | 'primary-dark' | 'accent-dark'

/** The roles the colour passed, in a fixed order: the words of the `data-brand` attribute. */
export function brandingRoles(branding: BrandingTokens | BrandingCheck): BrandRole[] {
  const check = 'light' in branding ? branding : checkBranding(branding)
  const roles: BrandRole[] = []
  for (const theme of BRAND_THEMES) {
    const verdict = check[theme]
    if (verdict.colour && verdict.primary && verdict.hover) roles.push(`primary-${theme}`)
    if (verdict.colour && verdict.accent) roles.push(`accent-${theme}`)
  }
  return roles
}

/**
 * The `--nds-brand-*` custom properties for a subtree: only the roles the colour passed, per theme. The names are written
 * out (they equal `BRAND_VARS`, which the test holds), so `check-token-resolution` sees where the stylesheet's
 * `var(--nds-brand-*)` get their values.
 */
export function brandingStyle(branding: BrandingTokens | BrandingCheck): BrandStyle {
  const { light, dark } = 'light' in branding ? branding : checkBranding(branding)
  const passed = (v: BrandThemeVerdict, role: 'primary' | 'accent') => (v.colour && (role === 'accent' ? v.accent : v.primary && v.hover) ? v.colour : null)
  const lp = passed(light, 'primary')
  const la = passed(light, 'accent')
  const dp = passed(dark, 'primary')
  const da = passed(dark, 'accent')
  return {
    ...(lp && light.hover ? { '--nds-brand-primary-light': lp, '--nds-brand-primary-hover-light': light.hover } : {}),
    ...(la ? { '--nds-brand-accent-light': la } : {}),
    ...(dp && dark.hover ? { '--nds-brand-primary-dark': dp, '--nds-brand-primary-hover-dark': dark.hover } : {}),
    ...(da ? { '--nds-brand-accent-dark': da } : {}),
  }
}

/** Spread on the root element of a branded subtree: `<div {...brandingAttrs(branding)}>`. */
export function brandingAttrs(branding: BrandingTokens | BrandingCheck): { 'data-brand': string; style: CSSProperties } {
  const check = 'light' in branding ? branding : checkBranding(branding)
  return { 'data-brand': brandingRoles(check).join(' '), style: brandingStyle(check) as CSSProperties }
}

// ── the generated stylesheet ────────────────────────────────────────────────────────────────────────────────────────

/** Matches an element in the light theme: not `.dark` and under no `.dark`. */
const lightOnly = (selector: string) => `${selector}:not(.dark, .dark *)`
/** Matches an element in the dark theme: under a `.dark`, or `.dark` itself. */
const darkOnly = (selector: string) => `.dark ${selector}, .dark${selector}`

/**
 * The rules of `styles/branding.css` (`tools/generate-tokens-css.ts` writes them). Each fires only for a role
 * `data-brand` names in the matching theme, so a role the colour failed keeps its inherited, design-system value. No
 * colour and no default appear in the file — only the mapping from `--nds-brand-*` to the tokens.
 */
export function brandBlocks(): ReadonlyArray<{ selector: string; vars: ReadonlyArray<{ section?: string; name: string; value: string }> }> {
  const primary = (theme: BrandTheme) => [
    { name: '--nds-primary', value: `var(${BRAND_VARS[theme].primary})` },
    { name: '--nds-primary-hover', value: `var(${BRAND_VARS[theme].hover})` },
  ]
  return [
    { selector: '[data-brand]', vars: [{ section: 'Branding: decoration follows the subtree\'s primary unless the accent passed', name: '--nds-brand-accent', value: 'var(--nds-primary)' }] },
    { selector: lightOnly("[data-brand~='primary-light']"), vars: primary('light') },
    { selector: lightOnly("[data-brand~='accent-light']"), vars: [{ name: '--nds-brand-accent', value: `var(${BRAND_VARS.light.accent})` }] },
    { selector: darkOnly("[data-brand~='primary-dark']"), vars: primary('dark') },
    { selector: darkOnly("[data-brand~='accent-dark']"), vars: [{ name: '--nds-brand-accent', value: `var(${BRAND_VARS.dark.accent})` }] },
  ]
}
